import {programs,clone,localDate,freshState,countSets,completedSets,validateBackup,validDate,mergeHistory,createWorkout,exercise} from './model.js';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,state=freshState(),storageOK=false,writeQueue=Promise.resolve(),restUntil=0,toastTimer;
const uid=()=>crypto.randomUUID();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function storageError(){storageOK=false;$('.local-badge').innerHTML='<span style="color:#a53728">Not saved · export a backup</span>';toast('Storage is unavailable. Export a backup before leaving.');}
function save(){const snapshot=clone(state);writeQueue=writeQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(Error('No storage'));const tx=db.transaction('notebook','readwrite');tx.objectStore('notebook').put(snapshot,'state');tx.oncomplete=()=>{storageOK=true;resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}));writeQueue.catch(storageError);return writeQueue;}
async function openDB(){try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('lift-log',1);r.onupgradeneeded=()=>r.result.createObjectStore('notebook');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Close other Lift Log tabs'));});const value=await new Promise((resolve,reject)=>{const tx=db.transaction('notebook');const r=tx.objectStore('notebook').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(value)state=validateBackup(value);storageOK=true;db.onversionchange=()=>{db.close();storageError();};}catch{storageError();}}
const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const sortedHistory=()=>[...state.history].sort((a,b)=>b.date.localeCompare(a.date));
const latestExercise=e=>sortedHistory().flatMap(w=>w.exercises).find(p=>p.name.toLowerCase()===e.name.toLowerCase()&&p.mode===e.mode&&p.sets.some(s=>s.done));
const setText=(e,s)=>e.mode==='bodyweight'&&s.weight===''?`${s.reps} reps`:`${s.weight||'—'} lb${e.mode==='assistance'?' assist':''} × ${s.reps||'—'}`;
function nextProgram(){const last=sortedHistory().find(w=>w.programId);return programs[(programs.findIndex(p=>p.id===last?.programId)+1)%4];}
function logEntries(list){return list.map(w=>`<details class="card history-item"><summary><div><h3>${esc(w.name)}</h3><p>${fmtDate(w.date)} · ${completedSets(w)} sets</p></div><span aria-hidden="true">＋</span></summary><div class="history-detail">${w.exercises.map(e=>`<p><strong>${esc(e.name)}</strong><br>${e.sets.map((s,i)=>`${i+1}. ${esc(setText(e,s))}${s.done?' ✓':' (unfinished)'}`).join('<br>')}${e.note?'<br>'+esc(e.note):''}</p>`).join('')}${w.notes?`<p>${esc(w.notes)}</p>`:''}<div class="button-row"><button class="secondary" data-action="edit" data-id="${esc(w.id)}">Edit</button><button class="danger" data-action="delete" data-id="${esc(w.id)}">Delete</button></div></div></details>`).join('');}
function today(){const p=nextProgram(),draft=state.draft,list=sortedHistory();return `<h1>Workouts</h1><section class="card new-log"><h2>${esc(draft?.name||p.name)}</h2>${draft?`<p class="hint">${fmtDate(draft.date)} · Draft</p>`:''}<button class="finish" data-action="${draft?'resume':'start'}" data-id="${p.id}">${draft?'Continue':'Start workout'}</button></section><div class="section-top"><h2>Logs</h2><span class="hint">${list.length}</span></div>${list.length?logEntries(list):'<p class="subtle">No logs yet.</p>'}`;}
function program(){return `<h1>Split</h1><div class="grid">${programs.map(p=>`<section class="card"><h2>${p.name}</h2><ul class="exercise-list">${p.exercises.map(e=>`<li>${e.name}<span>${e.sets.length} × ${e.min}–${e.max}</span></li>`).join('')}</ul><button class="secondary finish" data-action="start" data-id="${p.id}">Start log</button></section>`).join('')}</div>`;}
function session(){const w=state.draft;if(!w){location.hash='today';return '';}return `<div class="session-header"><div><p class="hint">${storageOK?'Saved locally':'Not saved'}</p><h1>${esc(w.name)}</h1></div><button class="secondary icon" data-action="leave" aria-label="Back to logs">←</button></div><div class="session-meta"><label>Date<input type="date" id="workout-date" value="${esc(w.date)}" required></label><label>Workout<input id="workout-name" maxlength="100" value="${esc(w.name)}"></label></div><div class="section-top"><span class="subtle" id="set-count">${completedSets(w)} / ${countSets(w)} sets checked</span><span class="badge">lb</span></div><div class="progress"><div id="progress-bar" style="width:${completedSets(w)/Math.max(1,countSets(w))*100}%"></div></div><div class="timer"><span>Rest <strong id="rest-time">${timerText()}</strong></span><div class="button-row"><button class="secondary" data-action="timer" data-seconds="90">90s</button><button class="secondary" data-action="timer" data-seconds="180">3m</button><button class="secondary" data-action="timer" data-seconds="0" aria-label="Stop rest timer">×</button></div></div>${w.exercises.map((e,i)=>{const last=latestExercise(e);return `<section class="card exercise"><div class="section-top"><div><h3>${esc(e.name)}</h3><p class="hint">${e.min}–${e.max} reps${e.note?' · '+esc(e.note):''}</p></div><button class="text-button" data-action="remove-exercise" data-e="${i}" aria-label="Remove ${esc(e.name)}">Remove</button></div>${last?`<p class="previous">Last: ${last.sets.filter(s=>s.done).map(s=>esc(setText(last,s))).join(' · ')}</p>`:''}<div class="set-head"><span>Set</span><span>${e.mode==='assistance'?'Assistance · lb':e.mode==='bodyweight'?'Added lb (optional)':'Weight · lb'}</span><span>Reps</span><span>Done</span></div>${e.sets.map((s,j)=>`<div class="set-row ${s.done?'completed':''}"><span class="set-no">${j+1}</span><input aria-label="${esc(e.name)} set ${j+1} ${e.mode==='assistance'?'assistance':'weight'} in pounds" inputmode="decimal" type="number" min="0" max="10000" step="0.5" placeholder="${e.mode==='bodyweight'?'BW':'lb'}" value="${esc(s.weight)}" data-e="${i}" data-s="${j}" data-field="weight"><input aria-label="${esc(e.name)} set ${j+1} reps" inputmode="numeric" type="number" min="1" max="10000" step="1" placeholder="${e.min}–${e.max}" value="${esc(s.reps)}" data-e="${i}" data-s="${j}" data-field="reps"><button class="check" aria-label="${esc(e.name)} set ${j+1} complete" aria-pressed="${s.done}" data-action="check" data-e="${i}" data-s="${j}">✓</button></div>`).join('')}<div class="button-row"><button class="text-button" data-action="add-set" data-e="${i}">+ Add set</button>${e.sets.length>1?`<button class="text-button" data-action="remove-set" data-e="${i}">Remove last set</button>`:''}</div></section>`;}).join('')}<button class="secondary" data-action="add-exercise">+ Add exercise</button><label style="margin-top:24px">Notes<textarea id="session-notes" maxlength="50000" placeholder="Notes">${esc(w.notes)}</textarea></label><button class="finish" data-action="finish">Save log</button><button class="text-button" data-action="discard">Discard draft</button>`;}
function history(){const list=sortedHistory();return `<h1>Logs</h1>${list.length?logEntries(list):'<p class="subtle">No logs yet.</p>'}`;}
function settings(){return `<h1>Settings</h1><section class="card settings-card"><h2>Backup</h2><div class="button-row"><button data-action="export">Export</button><button class="secondary" data-action="import">Import</button></div><input class="backup-input" id="backup-file" type="file" accept=".json,application/json"><p class="hint">${state.lastBackup?'Last export: '+esc(new Date(state.lastBackup).toLocaleString()):'No backup yet.'}</p><p class="hint">Logs are saved on this device. Export to Files before clearing website data.</p></section><section class="card settings-card"><h2>Install</h2><p>Safari → Share → Add to Home Screen.</p><p id="offline-status" class="status-label">Checking offline files…</p><button class="secondary" data-action="persist">Keep local storage</button></section>`;}
function render(){const route=location.hash.slice(1)||'today';$('#main').innerHTML=({today,program,session,history,settings}[route]||today)();document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.tab===(route==='session'?'today':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='settings')offlineStatus();}
async function confirm(title,copy,ok='Continue'){const d=$('#confirm');$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-ok').textContent=ok;d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='confirm'),{once:true}));}
async function clearDraftIfNeeded(){return !state.draft||await confirm('Replace your draft?','This replaces your unfinished log.','Replace draft');}
function updateProgress(){if(!state.draft)return;$('#set-count').textContent=`${completedSets(state.draft)} / ${countSets(state.draft)} sets checked`;$('#progress-bar').style.width=completedSets(state.draft)/Math.max(1,countSets(state.draft))*100+'%';}
function timerText(){const seconds=Math.max(0,Math.ceil((restUntil-Date.now())/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
setInterval(()=>{if($('#rest-time'))$('#rest-time').textContent=timerText();},500);
$('#main').addEventListener('input',event=>{const t=event.target,w=state.draft;if(!w)return;if(t.dataset.field){if(t.value!==''&&(!/^\d+(\.\d+)?$/.test(t.value)||Number(t.value)>10000||(t.dataset.field==='reps'&&(!Number.isInteger(Number(t.value))||Number(t.value)<1)))){t.setCustomValidity('Enter a valid positive number (up to 10000).');return;}t.setCustomValidity('');const s=w.exercises[Number(t.dataset.e)].sets[Number(t.dataset.s)];s[t.dataset.field]=t.value;if(t.dataset.field==='reps'&&!t.value){s.done=false;const row=t.closest('.set-row');row.classList.remove('completed');row.querySelector('button').setAttribute('aria-pressed','false');updateProgress();}}else if(t.id==='session-notes')w.notes=t.value;else if(t.id==='workout-name'){if(!t.value.trim())return;w.name=t.value.trim();}else if(t.id==='workout-date'){if(!validDate(t.value))return;w.date=t.value;}else return;save().catch(()=>{});});
$('#main').addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,w=state.draft,e=w?.exercises[Number(b.dataset.e)];try{
if(a==='start'){if(!await clearDraftIfNeeded())return;state.draft=createWorkout(programs.find(p=>p.id===b.dataset.id),state.history,uid(),localDate());await save();location.hash='session';render();}
if(a==='resume'){location.hash='session';}
if(a==='leave'){location.hash='today';}
if(a==='check'){const s=e.sets[Number(b.dataset.s)];if(!s.done&&(!s.reps||Number(s.reps)<1)){toast('Enter reps before checking this set.');return;}if(!s.done&&s.weight===''&&e.mode!=='bodyweight'){toast('Enter a weight (or assistance) first.');return;}s.done=!s.done;b.setAttribute('aria-pressed',s.done);b.closest('.set-row').classList.toggle('completed',s.done);updateProgress();await save();}
if(a==='add-set'){e.sets.push({weight:e.sets.at(-1)?.weight||'',reps:'',done:false});await save();render();}
if(a==='remove-set'){if(e.sets.at(-1).done&&!await confirm('Remove completed set?','This removes the last set from this draft.','Remove set'))return;e.sets.pop();await save();render();}
if(a==='remove-exercise'){if(!await confirm('Remove exercise?',`Remove ${e.name} and its sets from this session?`,'Remove'))return;w.exercises.splice(Number(b.dataset.e),1);await save();render();}
if(a==='add-exercise'){const name=prompt('Exercise name');if(!name?.trim())return;w.exercises.push(exercise(name.trim().slice(0,100),2,8,12));await save();render();}
if(a==='timer'){restUntil=Number(b.dataset.seconds)?Date.now()+Number(b.dataset.seconds)*1000:0;$('#rest-time').textContent=timerText();}
if(a==='finish'){if(!$('#workout-date').reportValidity()||!$('#workout-name').value.trim()||![...$('#main').querySelectorAll('input')].every(i=>i.reportValidity()))return;if(!completedSets(w)){toast('Complete at least one set before finishing.');return;}if(!await confirm('Save log?',`${completedSets(w)} of ${countSets(w)} sets are checked. Unchecked sets remain unfinished.`,'Save log'))return;const record=clone(w);const index=state.history.findIndex(x=>x.id===record.id);if(index>=0)state.history[index]=record;else state.history.push(record);state.draft=null;await save();restUntil=0;location.hash='today';toast('Log saved.');}
if(a==='discard'){if(!await confirm('Discard draft?','This removes the current draft. Saved logs are kept.','Discard draft'))return;state.draft=null;await save();location.hash='today';}
if(a==='edit'){if(!await clearDraftIfNeeded())return;state.draft=clone(state.history.find(x=>x.id===b.dataset.id));await save();location.hash='session';}
if(a==='delete'){if(!await confirm('Delete saved session?','Export a backup first if you want to keep a copy. This cannot be undone.','Delete session'))return;state.history=state.history.filter(x=>x.id!==b.dataset.id);await save();render();}
if(a==='export')await exportBackup();
if(a==='import')$('#backup-file').click();
if(a==='persist'){const granted=await navigator.storage?.persist?.();toast(granted?'Persistent storage granted. Keep exporting backups.':'Storage request not granted. Keep regular backups.');}
}catch(error){toast('Could not complete that action. '+error.message);}});
function downloadBackup(file){const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportBackup(){const time=new Date().toISOString(),backup={...clone(state),lastBackup:time};const file=new File([JSON.stringify(backup,null,2)],`healthspan-training-${localDate()}.json`,{type:'application/json'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Healthspan training backup'});}catch(error){if(error.name==='AbortError')return;downloadBackup(file);}}else downloadBackup(file);state.lastBackup=time;try{await save();}catch{}if(location.hash==='#settings')render();toast('Backup export requested. Keep the file in Files.');}
$('#main').addEventListener('change',async event=>{if(event.target.id!=='backup-file')return;const file=event.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Backup is too large (20 MB maximum).');const incoming=validateBackup(JSON.parse(await file.text()));const added=incoming.history.filter(w=>!state.history.some(x=>x.id===w.id)).length;if(!await confirm('Import this notebook?',`Add ${added} new sessions. Existing session IDs are kept. ${incoming.draft?(state.draft?'Your current draft will be kept.':'The backup draft will be restored.'):'No draft in this backup.'}`,'Import'))return;state.history=mergeHistory(state.history,incoming.history);if(!state.draft&&incoming.draft)state.draft=incoming.draft;await save();render();toast(`Imported ${added} sessions.`);}catch(error){toast('Import failed: '+error.message);}finally{if($('#backup-file'))$('#backup-file').value='';}});
let offlineReady=false;
async function offlineStatus(){if(!$('#offline-status'))return;try{const keys=await caches.keys();offlineReady=keys.some(k=>k.startsWith('lift-log-shell-'));}catch{}if($('#offline-status'))$('#offline-status').textContent=offlineReady?'Available offline.':'Offline files not ready. Keep this open online.';}
window.addEventListener('hashchange',()=>{render();scrollTo(0,0);});
await openDB();render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(registration=>{const activate=()=>registration.waiting?.postMessage({type:'ACTIVATE_UPDATE'});activate();registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')activate();});});return navigator.serviceWorker.ready;}).then(()=>{offlineReady=true;offlineStatus();}).catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Offline setup failed. Try again online.';});}

let reloadingForUpdate=false;navigator.serviceWorker?.addEventListener('controllerchange',async()=>{if(reloadingForUpdate)return;reloadingForUpdate=true;try{await writeQueue;}catch{}location.reload();});
